PACKS = json.loads('{"state:DC": [{"id": "d22b148c3d", "as_of": "2026-10-02 (page read)", "claim": "DC deed recordation tax (District of Columbia, per CFO tax rates page): 1.1% of consideration/fair market value for residential transfers under $400,000, and 1.45% on the entire amount if the transfer is $400,000 or more (the page words the higher tier as \'greater than $400,000\').", "topic": "taxes", "saved_at": "2026-10-02T00:57:43.055138+00:00", "confidence": 0.92, "source_url": "https://cfo.dc.gov/page/tax-rates-and-revenues-property-taxes", "source_name": "DC Office of the CFO – Tax Rates and Revenues, Property Taxes"}, {"id": "57fb6d9fc3", "as_of": "2026-10-02 (page read)", "claim": "DC deed transfer tax (District of Columbia, per CFO page): same tiers as recordation – 1.1% for residential transfers under $400,000 and 1.45% on the entire amount if the transfer is over $400,000. It is levied when the deed is submitted for recordation. The CFO page notes the rate is 1.1% for residential under $400,000.", "topic": "taxes", "saved_at": "2026-10-02T00:57:43.055138+00:00", "confidence": 0.92, "source_url": "https://cfo.dc.gov/page/tax-rates-and-revenues-property-taxes", "source_name": "DC Office of the CFO – Tax Rates and Revenues, Property Taxes"}, {"id": "27fe6ef7ec", "as_of": "2026 (undated page)", "claim": "Customary split in DC: the party responsible for the recordation/transfer taxes is negotiable between buyer and seller, but typically the seller pays the transfer tax and the buyer pays the recordation tax (per a DC settlement company FAQ, not a government source).", "topic": "taxes", "saved_at": "2026-10-02T00:57:43.055138+00:00", "confidence": 0.7, "source_url": "https://www.smartsettlements.com/blog-post/smart-faq-about-the-dc-transfer-and-recordation-tax", "source_name": "Smart Settlements – FAQ about DC Transfer and Recordation Tax"}, {"id": "99528ebdda", "as_of": "2026-07-01", "claim": "DC HPAP (DHCD): gives up to $202,000 in gap financing/down payment assistance to eligible first-time homebuyers, plus separate closing-cost assistance of up to $4,000, scaled by household income and size. Limits apply to HPAP loans closing after July 1, 2026 (FY2026 table dated July 2026); effective date is by loan closing date, not application date.", "topic": "regulation", "saved_at": "2026-10-02T00:57:43.055138+00:00", "confidence": 0.95, "source_url": "https://dhcd.dc.gov/publication/dhcd-hpap-income-assistance-table-july-2026", "source_name": "DC DHCD – HPAP Income Assistance Table July 2026"}, {"id": "ad46517e12", "as_of": "2026-10-02 (page read)", "claim": "HPAP applicant contribution: recipients contribute $500 or 50% of liquid assets above $3,000, whichever is greater (director may waive the excess over $500 for very low- and low-income applicants). Applicants must be head of household, first-time homebuyer, and very low- to moderate-income.", "topic": "regulation", "saved_at": "2026-10-02T00:57:43.055138+00:00", "confidence": 0.9, "source_url": "https://dhcd.dc.gov/page/hpap-eligibility-how-apply-and-program-details", "source_name": "DC DHCD – HPAP Eligibility, How to Apply and Program Details"}, {"id": "1393383f2f", "as_of": "2026-10-02 (page read)", "claim": "DCHFA HomeAdvantage DC (mortgage revenue bond loan) requires household income within MRB income limits (all occupants 18+ counted), minimum credit score 640. DC Open Doors is a DCHFA program offering a deferred repayable Down Payment Assistance Loan (DPAL) and closing cost assistance; one DCHFA page lists a maximum household income of 130% AMI as published by DCHFA for a program on that page. Exact current DPAL dollar limits were not verified.", "topic": "regulation", "saved_at": "2026-10-02T00:57:43.055138+00:00", "confidence": 0.6, "source_url": "https://dchfa.org/homeownership/do-i-qualify/", "source_name": "DCHFA – Do I Qualify / DC Open Doors"}, {"id": "61dc63e04f", "as_of": "Tax year 2026", "claim": "DC homestead deduction for tax year 2026 is $91,950 (per DC Fiscal Policy Institute). A real estate site dated Sept 2026 says $87,600 and a standard residential rate of 0.85% of assessed value; those two sources disagree on the deduction, so use the DCFPI figure only after confirming on OTR. DC assesses real property at 100% of market value, and Class 1 is occupied residential.", "topic": "taxes", "saved_at": "2026-10-02T00:57:43.055138+00:00", "confidence": 0.6, "source_url": "https://dcfpi.org/all/where-dc-gets-its-money-residential-property-tax/", "source_name": "DC Fiscal Policy Institute; DC CFO"}, {"id": "7ec1aa2d35", "as_of": "2026-10-02 (page read)", "claim": "DC Seller\'s Disclosure Statement: sellers of residential property of no more than four units must give prospective buyers a real property disclosure statement under D.C. Code § 42-1301 et seq. before or at contract execution. If delivered after the buyer signs, the buyer may terminate by written notice within 5 calendar days of receiving it (D.C. Code § 42-1302(c)). DLCP publishes a consumer advisory on the right to the statement.", "topic": "regulation", "saved_at": "2026-10-02T00:57:43.055138+00:00", "confidence": 0.85, "source_url": "https://code.dccouncil.gov/us/dc/council/code/sections/42-1302", "source_name": "DC Code § 42-1302; DLCP; Nolo"}, {"id": "ff0f677728", "as_of": "2026-10-02 (page read)", "claim": "DC TOPA: since a July 2018 amendment, single-family homes are exempt from TOPA unless occupied by an elderly (62+) or disabled tenant (PolicyLink). DC\'s Front Door site says some tenants may buy a single-family home they rent if the landlord sells, and that multi-unit buildings follow a different process and timeline. In February 2025 the Mayor proposed the RENTAL Act, which would change TOPA; I did not verify whether it was enacted.", "topic": "regulation", "saved_at": "2026-10-02T00:57:43.055138+00:00", "confidence": 0.7, "source_url": "https://www.frontdoor.dc.gov/topa", "source_name": "DC Front Door (dc.gov) / PolicyLink"}], "state:DE": [{"id": "1cdcfae696", "as_of": "2024-25 form edition", "claim": "Delaware Division of Revenue RTT instructions (form 2024-25 edition) state the realty transfer tax rate paid to the State, county and/or municipality combined is 4.0% of the value of the property conveyed; the same form notes it also applies to leases of residential property over 5 years.", "topic": "taxes", "saved_at": "2026-10-02T00:54:06.753101+00:00", "confidence": 0.9, "source_url": "https://revenuefiles.delaware.gov/2024/Business_Tax_Forms_2024_2025/RTT-TAX_2024-01_Instructions.pdf", "source_name": "Delaware Division of Revenue – RTT Instructions"}, {"id": "edd358165f", "as_of": "current page, retrieved 2026-10-02", "claim": "Delaware Division of Revenue says that since August 2017 the state realty transfer tax rate is 2.5% where the county/municipality imposes a local transfer tax, and 3% where no local transfer tax is imposed. Local portion on the State Form 5402 is 1.5% (county or municipality), giving the typical 4% total (2.5% state + 1.5% local).", "topic": "taxes", "saved_at": "2026-10-02T00:54:06.753101+00:00", "confidence": 0.85, "source_url": "https://revenue.delaware.gov/first-time-home-buyer-tax-credit/", "source_name": "Delaware Division of Revenue – First-time Home Buyer Tax Credit page; Form 5402 (New Castle County copy)"}, {"id": "a82caa32a7", "as_of": "2026-10-02", "claim": "Customary split: the Division of Revenue describes the 2.5% state rate as assessed half on the buyer and half on the seller (1.25% each). Secondary sources (HomeLight, AmeriSave) say the total 4% is customarily split equally between buyer and seller. Note: this is a custom, negotiable in the contract; the state\'s legal division is equal between grantor and grantee. A Delaware Dept. of Finance summary PDF (financefiles.delaware.gov/docs/rtt.pdf) still shows older 3.0% state figure and appears outdated; the Division of Revenue is more authoritative.", "topic": "taxes", "saved_at": "2026-10-02T00:54:06.753101+00:00", "confidence": 0.7, "source_url": "https://revenue.delaware.gov/first-time-home-buyer-tax-credit/", "source_name": "Delaware Division of Revenue; HomeLight (secondary)"}, {"id": "b34354a66b", "as_of": "effective 2017-08-01; current as read 2026-10-02", "claim": "First-time home buyer reduction (HB 172, 30 Del. C. §5402(c)): for transactions on or after Aug 1, 2017, the transfer tax portion payable by a first-time home buyer is reduced by 0.5% multiplied by the lesser of the property value or $400,000 (maximum reduction $2,000).", "topic": "taxes", "saved_at": "2026-10-02T00:54:06.753101+00:00", "confidence": 0.9, "source_url": "https://legis.delaware.gov/json/BillDetail/GenerateHtmlDocument?legislationId=68651&legislationTypeId=1&docTypeId=2&legislationName=HB172", "source_name": "Delaware General Assembly – HB 172"}, {"id": "50ace6b1a0", "as_of": "2025 Delaware Code", "claim": "Delaware Code Title 6 §2572 requires a seller transferring residential real property to disclose in writing to the buyer, agent and subagent all known material defects of the property (subject to the exclusions in §2577). Per a secondary source (Houwzer), §2573 requires the Seller\'s Disclosure of Real Property Condition Report be given to prospective buyers or their agent before the buyer makes an offer.", "topic": "regulation", "saved_at": "2026-10-02T00:54:06.753101+00:00", "confidence": 0.85, "source_url": "https://law.justia.com/codes/delaware/title-6/chapter-25/subchapter-vii/section-2572/", "source_name": "Justia – 2025 Delaware Code Title 6 §2572"}, {"id": "ffadef176e", "as_of": "effective 2025-08-01", "claim": "The Delaware Real Estate Commission publishes a \'Seller\'s Disclosure and Radon Disclosure Exemption\' form (approved effective Aug 1, 2025) for sellers who are exempt from completing the disclosure; it cites Chapter 25, Title 6 of the Delaware Code as the requirement for sellers of residential property to disclose known material defects in writing.", "topic": "regulation", "saved_at": "2026-10-02T00:54:06.753101+00:00", "confidence": 0.85, "source_url": "https://dprfiles.delaware.gov/realestate/DREC_Property_Disclosure_Exemption.pdf", "source_name": "Delaware Division of Professional Regulation – DREC Property Disclosure Exemption"}, {"id": "fc4a13694f", "as_of": "retrieved 2026-10-02 (article date not confirmed)", "claim": "Delaware is an attorney-settlement state: law-firm commentary states all real estate settlements for property in Delaware must be performed by a Delaware-licensed attorney (not a title/escrow company), consistent with Delaware Supreme Court authority on the unauthorized practice of law.", "topic": "regulation", "saved_at": "2026-10-02T00:54:06.753101+00:00", "confidence": 0.75, "source_url": "https://www.jdsupra.com/legalnews/delaware-real-estate-closings-why-5210016/", "source_name": "JD Supra (law firm article); Coastal Point"}, {"id": "f4783fe5db", "as_of": "2026-06-19", "claim": "Between 2021 and 2025 all three Delaware counties conducted property reassessments: New Castle County\'s first since 1987 (per House Democrats press release; Spotlight Delaware cites 1983 values), Kent\'s since 1987, Sussex\'s since 1974. In June 2026 the Delaware House passed 6 bills to standardize the statewide reassessment process.", "topic": "taxes", "saved_at": "2026-10-02T00:54:06.753101+00:00", "confidence": 0.85, "source_url": "https://housedems.delaware.gov/2026/06/19/house-addresses-issues-in-statewide-property-reassessment-process/", "source_name": "Delaware House Democrats press release"}, {"id": "18111228ff", "as_of": "2026-02-20", "claim": "Spotlight Delaware: before reassessment Sussex County taxed at 50% of 1976 assessed value, Kent at 60% of 1987 value, and New Castle at 100% of 1983 value; now all three counties apply tax rates to 100% of assessed value. Kent finished a year earlier (data 2023 vs 2024 tax years) than New Castle and Sussex (2024 vs 2025 tax years). New Castle\'s temporary higher commercial-property tax shift was described as a short-term fix due to expire in 2026.", "topic": "taxes", "saved_at": "2026-10-02T00:54:06.753101+00:00", "confidence": 0.8, "source_url": "https://spotlightdelaware.org/2026/02/20/spotlight-delawares-reassessment-map-explained/", "source_name": "Spotlight Delaware – Reassessment Map Explained"}], "state:MD": [{"id": "be9a7a5f57", "as_of": "2026-09 (page current when read)", "claim": "Maryland\'s state transfer tax is 0.5% of consideration; for deeds to a first-time Maryland homebuyer it is 0.25% (Clerk of Circuit Court, Frederick County page citing Tax-Property Art. §13-207).", "topic": "taxes", "saved_at": "2026-10-02T00:55:40.322133+00:00", "confidence": 0.85, "source_url": "https://www.courts.state.md.us/clerks/frederick/recordingfees", "source_name": "Maryland Courts – Frederick County Clerk, recording fees"}, {"id": "1b4092d39b", "as_of": "2026 (current pages)", "claim": "For a first-time Maryland homebuyer who will occupy the property as a principal residence, the state transfer tax rate is 0.25% and, per law firm Gordon Feinblatt\'s rate chart, it must be paid by the seller (i.e., the buyer\'s half is waived). Another title-company page (Federal Title) describes it the same way: the 0.5% is typically split evenly and the buyer\'s 0.25% share is waived; it says the exemption is not a three-year lookback and a prior Maryland principal residence disqualifies the buyer. A different title-company page (ATG Title) states a three-year lookback, so the sources conflict. Confirm the definition against Tax-Property §13-207 before publishing.", "topic": "taxes", "saved_at": "2026-10-02T00:55:40.322133+00:00", "confidence": 0.7, "source_url": "https://www.gfrlaw.com/what-we-do/insights/recordation-and-transfer-tax-rates-maryland-explained", "source_name": "Gordon Feinblatt LLC; Federal Title"}, {"id": "d894a29ab5", "as_of": "2026 (current page)", "claim": "Customary split: in Maryland the seller and buyer customarily split the total transfer and recordation tax amount equally when no exemptions apply (Smart Settlements, a title/settlement company, so a customary-practice statement rather than law).", "topic": "taxes", "saved_at": "2026-10-02T00:55:40.322133+00:00", "confidence": 0.75, "source_url": "https://www.smartsettlements.com/blog-post/smart-faq-about-maryland-transfer-and-recordation-taxes", "source_name": "Smart Settlements – FAQ on MD transfer and recordation taxes"}, {"id": "84949db3b7", "as_of": "2026 (current pages; conflicting source noted)", "claim": "County rate chart from Gordon Feinblatt (county-level, not town): Baltimore County recordation 0.5%, local transfer 1.5%, state transfer 0.5%, total 2.5%. Howard County recordation 0.5%, local transfer 1.25%, total 2.25%. Montgomery County local transfer generally 1.0% with a recordation chart that varies by price. Prince George\'s County recordation 0.55%, local transfer 1.4%, total 2.45%. Anne Arundel County local transfer 1.0%, or 1.5% if consideration is $1M or more, and recordation 0.7%. Note: a separate title-industry table (FNIS recording tax table) lists Howard transfer tax at 1.0%, which conflicts with the 1.25% in the law-firm chart. Verify Howard against the Howard County/Clerk page before publishing.", "topic": "taxes", "saved_at": "2026-10-02T00:55:40.322133+00:00", "confidence": 0.6, "source_url": "https://www.gfrlaw.com/what-we-do/insights/recordation-and-transfer-tax-rates-maryland-explained", "source_name": "Gordon Feinblatt LLC; FNIS Maryland recording tax table"}, {"id": "e6ea83a198", "as_of": "CY/FY 2025", "claim": "The Maryland Dept. of Legislative Services 2025 county local tax rate publication notes that Montgomery County imposes a recordation tax surcharge on transactions over $600,000, and Anne Arundel County imposes a 0.5% transfer tax surcharge on transactions of $1 million or more. Its listed Prince George\'s County local transfer tax is 1.4%.", "topic": "taxes", "saved_at": "2026-10-02T00:55:40.322133+00:00", "confidence": 0.8, "source_url": "https://dls.maryland.gov/pubs/prod/NoPblTabPDF/2025CountyLocalTaxRates.pdf", "source_name": "Maryland Dept. of Legislative Services – County Local Tax Rates (2025)"}, {"id": "d458cc6211", "as_of": "2025 code / current form", "claim": "Real Property Article §10-702 requires the seller of certain single-family residential property to deliver to the purchaser either a written Residential Property Disclaimer Statement (seller sells \'as is\' with no representations or warranties) or a Residential Property Disclosure Statement. The Real Estate Commission provides a single standardized form. Even when selling \'as is\', the seller must disclose latent defects of which the seller has actual knowledge. Latent defects are material defects that a buyer could not readily observe and that would pose a direct threat to health or safety. The form lists exemptions, including sale of unimproved real property.", "topic": "regulation", "saved_at": "2026-10-02T00:55:40.322133+00:00", "confidence": 0.85, "source_url": "https://www.dllr.state.md.us/forms/propertydanddform.pdf", "source_name": "Maryland DLLR/Real Estate Commission form; Justia Md. Code RP §10-702"}, {"id": "c4a98a2cdf", "as_of": "2026 (current pages)", "claim": "Homestead Property Tax Credit: every Maryland county and municipality must limit annual taxable assessment increases on a principal residence to 10% or less. The state property tax calculation uses the 10% cap and local taxes use the local cap, which may be lower. It is a credit on the portion of an increase above the cap. It does not limit market value, applies only when the annual increase exceeds the cap, and requires a one-time application. The credit does not apply if the property was transferred to a new owner, so a buyer must apply. SDAT administers it.", "topic": "taxes", "saved_at": "2026-10-02T00:55:40.322133+00:00", "confidence": 0.9, "source_url": "https://dat.maryland.gov/realproperty/pages/maryland-homestead-tax-credit.aspx", "source_name": "Maryland SDAT – Homestead Tax Credit; Prince George\'s County Finance"}, {"id": "27bfc123d0", "as_of": "current; phase-in rule per 2018-12-28 release", "claim": "Maryland reassesses real property on a three-year cycle: SDAT reviews one-third of all properties each year (Group 1/2/3). Increases in value are phased in equally over three years while decreases take effect fully at once (from a 2018 SDAT release describing the phase-in rule).", "topic": "taxes", "saved_at": "2026-10-02T00:55:40.322133+00:00", "confidence": 0.85, "source_url": "https://dat.maryland.gov/About/Pages/default.aspx", "source_name": "Maryland SDAT – About the Department; SDAT 2019 reassessment release"}, {"id": "97f7a8685c", "as_of": "state rate current; county rates FY 2025", "claim": "The Maryland state real property tax rate is $0.112 per $100 of assessed value (listed in Howard County\'s rate schedule, which also lists a fire tax of $0.2060 per $100). County rates are additional and vary. DLS shows FY2025 county rates per $100 of 0.9830 Anne Arundel, 1.1000 Baltimore County, 1.2500 Howard, 1.0392 Montgomery, 1.3740 Prince George\'s. These are county rates and exclude state tax, special taxes and municipal taxes.", "topic": "taxes", "saved_at": "2026-10-02T00:55:40.322133+00:00", "confidence": 0.8, "source_url": "https://www.howardcountymd.gov/finance/real-property-tax", "source_name": "Howard County Finance; Maryland DLS County Local Tax Rates 2025"}], "state:NJ": [{"id": "7ec8e4edd0", "as_of": "2026-10 (current page)", "claim": "NJ Division of Taxation: the Realty Transfer Fee (RTF) is imposed on the SELLER at deed recording. Standard rates for total consideration not over $350,000: $2.00 per $500 on the first $150,000; $3.35 per $500 from $150,000 to $200,000; $3.90 per $500 from $200,000 to $350,000. For consideration over $350,000: $2.90 per $500 on first $150,000; $4.25 per $500 from $150,000 to $200,000; $4.80 per $500 from $200,000 to $550,000 (higher bands above $550,000 exist but were not visible in the text read).", "topic": "taxes", "saved_at": "2026-10-02T00:52:52.543451+00:00", "confidence": 0.9, "source_url": "https://www.nj.gov/treasury/taxation/realty.shtml", "source_name": "NJ Division of Taxation – Realty Transfer Fee"}, {"id": "c9b0ec1a98", "as_of": "2026", "claim": "Third-party RTF calculator lists the higher standard bands for consideration over $350,000 as $5.30 per $500 for $550,001–$850,000 and $5.80 per $500 for $850,001–$1,000,000 (secondary source; official page text read did not show these rows – verify against the Division of Taxation rate schedule before publishing).", "topic": "taxes", "saved_at": "2026-10-02T00:52:52.543451+00:00", "confidence": 0.6, "source_url": "https://transfertaxcalculator.com/new-jersey-realty-transfer-fee-calculator/", "source_name": "transfertaxcalculator.com"}, {"id": "eb1b92b263", "as_of": "Contracts executed on/after 2025-07-10; page read 2026-10", "claim": "The old buyer-paid 1% \'mansion tax\' on sales over $1M was ELIMINATED for contracts fully executed on or after July 10, 2025 (N.J.S.A. 46:15-7.2). It was replaced by a Graduated Percent Fee paid by the SELLER on sales over $1 million: 1% ($1M+), 2% ($2M+), 2.5% ($2.5M+), 3% ($3M+), 3.5% ($3.5M and above). It is separate from and in addition to the standard RTF. Blog should not say buyers pay the mansion tax for current contracts. (NJ REALTORS summary words the tiers as \'on amounts in excess of\'; some secondary sources say the bracket rate applies to the entire price – confirm exact calculation method with Division of Taxation/Treasury memos.)", "topic": "taxes", "saved_at": "2026-10-02T00:52:52.543451+00:00", "confidence": 0.85, "source_url": "https://www.njrealtor.com/government-affairs/realty-transfer-fee/", "source_name": "NJ REALTORS – Graduated Percent Fee (cites Treasury memos)"}, {"id": "fdc7210e05", "as_of": "2026-10", "claim": "Division of Taxation confirms a Graduated Percent Fee is imposed as a supplemental fee to the RTF on recording of deeds for sales over $1,000,000, with percentage rates graduated by total consideration.", "topic": "taxes", "saved_at": "2026-10-02T00:52:52.543451+00:00", "confidence": 0.9, "source_url": "https://www.nj.gov/treasury/taxation/realty.shtml", "source_name": "NJ Division of Taxation – Realty Transfer Fee"}, {"id": "4163b890e7", "as_of": "2026-04", "claim": "Attorney review: under NJ rules (N.A.C. 11:5-6.2(g)) residential sale contracts prepared by a licensee must state on the first page that the contract becomes final in three business days unless an attorney disapproves it. It applies to 1–4 family properties and vacant one-family lots; the clause cannot be waived (a party may simply choose not to consult an attorney). During review either party\'s attorney can cancel/disapprove (secondary source: law firm guide citing the regulation and Denesevich v. Moran).", "topic": "regulation", "saved_at": "2026-10-02T00:52:52.543451+00:00", "confidence": 0.8, "source_url": "https://www.earlwhite.law/blog/attorney-review-new-jersey/", "source_name": "Law Firm of Earl P. White – Attorney Review in NJ (updated 2026-04-13)"}, {"id": "bb9573a776", "as_of": "2024-08-01 (law effective)", "claim": "Seller disclosure: the Real Estate Consumer Protection Enhancement Act (S3192/A4454, signed July 2024, effective Aug. 1, 2024) requires sellers to give buyers a signed, completed Property Condition Disclosure Statement before the buyer becomes contractually obligated; applies to all residential sales, including bank-owned properties and estates.", "topic": "regulation", "saved_at": "2026-10-02T00:52:52.543451+00:00", "confidence": 0.85, "source_url": "https://www.njrealtor.com/government-affairs/cpea/", "source_name": "NJ REALTORS – Consumer Protection Enhancement Act"}, {"id": "7c14206c59", "as_of": "2024-03-20", "claim": "Since March 20, 2024 all NJ sellers must provide the Property Condition Disclosure Statement (form issued by NJ Division of Consumer Affairs), which includes flood history/flood risk questions (questions 109–117) and whether the property is in a FEMA Special or Moderate Risk Flood Hazard Area; commercial/industrial sellers must also disclose known flood risk (law-firm alert).", "topic": "regulation", "saved_at": "2026-10-02T00:52:52.543451+00:00", "confidence": 0.8, "source_url": "https://www.saul.com/insights/alert/mandatory-disclosure-rules-all-new-jersey-sellers-and-landlords-residential", "source_name": "Saul Ewing alert on NJ Flood Disclosure Law"}, {"id": "5b4cf9aeab", "as_of": "2024 data (published 2026-03)", "claim": "Tax Foundation (Property Taxes by State and County, 2026 edition, updated 2026-03-17): New Jersey ranks #1 for effective property tax rate – 1.88% of owner-occupied housing value in 2024 (down from 1.98% in 2023), tied at 1.88% with Illinois in its Table 2. Its county analysis, using calendar-2023 data, cites NJ at 2.23% on owner-occupied property (Illinois 2.07%, Connecticut 1.92%), and names Camden and Salem counties NJ among the five counties with burdens above 2.95%. Figures differ by methodology/year; cite year and table explicitly. Non-government source.", "topic": "taxes", "saved_at": "2026-10-02T00:52:52.543451+00:00", "confidence": 0.75, "source_url": "https://taxfoundation.org/data/all/state/property-taxes-by-state-county/", "source_name": "Tax Foundation"}, {"id": "60e80cd80d", "as_of": "2026-09", "claim": "ANCHOR 2026 cycle (based on 2025 residency, income, age): eligible homeowners and renters can receive up to $1,750 per FOX5 reporting; payments begin Sept. 15, 2026; seniors/disability recipients must file the combined PAS-1 (covers ANCHOR, Senior Freeze, Stay NJ); deadline for PAS-1 or manual ANC-1 is Nov. 2, 2026. Many under-65 prior filers are auto-enrolled. (News source, not NJ Treasury – verify the $1,750 maximum.)", "topic": "taxes", "saved_at": "2026-10-02T00:52:52.543451+00:00", "confidence": 0.7, "source_url": "https://www.fox5ny.com/news/nj-anchor-program-2026-eligibility-deadlines-payments", "source_name": "FOX 5 New York"}, {"id": "a4756f83e8", "as_of": "2026", "claim": "Stay NJ is for eligible homeowners age 65+: reimburses 50% of property tax bills, up to a maximum of $13,000 benefit, with a 2025 benefit cap of $6,500 (per a municipal page); paid in quarterly installments, calculated after ANCHOR and Senior Freeze; 2025 combined PAS-1 deadline Nov. 2, 2026; benefits subject to change by State Budget. (Municipal summary of state program – New Providence NJ.)", "topic": "taxes", "saved_at": "2026-10-02T00:52:52.543451+00:00", "confidence": 0.65, "source_url": "https://www.newprov.us/241/Tax-Relief-Programs", "source_name": "Borough of New Providence – Tax Relief Programs"}], "state:PA": [{"id": "35123e0088", "as_of": "2026-10 (page read 2026-10-02)", "claim": "Pennsylvania realty transfer tax is imposed at 1 percent on the value of real estate transferred by deed or other instrument; both grantor and grantee are jointly and severally liable. County Recorders of Deeds collect it along with any local realty transfer tax and remit the state\'s 1% to the Department of Revenue; locals may share their tax between school districts and municipalities.", "topic": "taxes", "saved_at": "2026-10-02T00:13:27.978279+00:00", "confidence": 0.95, "source_url": "https://www.pa.gov/agencies/revenue/resources/tax-types-and-information/realty-transfer-tax", "source_name": "PA Department of Revenue – Realty Transfer Tax"}, {"id": "95b3af9ce2", "as_of": "2026-10 (page read 2026-10-02)", "claim": "PA Department of Revenue: the 1% state realty transfer tax is due when the title-transferring document is filed with the county Recorder of Deeds; a local realty transfer tax of 1 percent (more in some localities) is also due. Parties may agree by private contract to split the tax any way they like, though both remain jointly liable to the state.", "topic": "taxes", "saved_at": "2026-10-02T00:13:27.978279+00:00", "confidence": 0.9, "source_url": "https://www.pa.gov/agencies/revenue/resources/tax-types-and-information/realty-transfer-tax/new-home-construction", "source_name": "PA Department of Revenue – Realty Transfer Tax and New Home Construction Q&A"}, {"id": "daa2c239ab", "as_of": "2025-04", "claim": "Law-firm summary (Saul Ewing, April 2025): the general rule of thumb is a 2% total tax on consideration, 1% to the state and the remainder to the municipality and/or school district, though many municipalities set different local rates (Philadelphia is a notable outlier). The tax customarily is split between buyer and seller, though parties can negotiate who bears it. Secondary (law firm) source, not a government source on the customary 50/50 split; the specific local split of 0.5%/0.5% municipality/school district was not verified by me.", "topic": "taxes", "saved_at": "2026-10-02T00:13:27.978279+00:00", "confidence": 0.7, "source_url": "https://www.saul.com/sites/default/files/documents/2025-04/Understanding%20Realty%20Transfer%20Tax%20Basics%20in%20Pennsylvania.pdf", "source_name": "Saul Ewing – Understanding Realty Transfer Tax Basics in Pennsylvania"}, {"id": "21e78a5b22", "as_of": "2026-10 (current page)", "claim": "City of Philadelphia: Realty Transfer Tax is 3.578% (City) + 1% (Commonwealth) = 4.578% total, based on sale price or assessed value plus assumed debt; it is due when the document is recorded. (EY tax news confirms the City increase from 3.278% to 3.578% effective July 1, 2025. Older phila.gov blog posts citing 3.27%/4.27% are outdated.)", "topic": "taxes", "saved_at": "2026-10-02T00:13:27.978279+00:00", "confidence": 0.95, "source_url": "https://www.phila.gov/services/payments-assistance-taxes/taxes/property-and-real-estate-taxes/realty-transfer-tax/", "source_name": "City of Philadelphia – Realty Transfer Tax"}, {"id": "b1a15bca3e", "as_of": "2025-07-01", "claim": "Philadelphia\'s transfer tax increase from 3.278% to 3.578%, effective July 1, 2025, was enacted via City Bill No. 250211-00 (as reported by EY Tax News, 4 Aug 2025).", "topic": "taxes", "saved_at": "2026-10-02T00:13:27.978279+00:00", "confidence": 0.85, "source_url": "https://taxnews.ey.com/news/2025-1650-realty-transfer-tax-and-recordation-fee-updates-in-new-jersey-pennsylvania-the-city-of-philadelphia-and-rhode-island", "source_name": "EY Tax News"}, {"id": "576e5da36b", "as_of": "2026-10 (current page; no page date shown)", "claim": "Keystone Advantage Assistance Loan (PHFA): second mortgage giving up to 4% of the purchase price or market value or $6,000, whichever is less, for down payment and closing costs, repaid monthly, amortized over 10 years at 0% interest. Usable with HFA Preferred (Lo MI), Keystone Government and Keystone Home loans. (PHFA\'s separate assistance page notes EAH-employer participants may receive up to $8,000 on the same 10-year, 0% terms.)", "topic": "regulation", "saved_at": "2026-10-02T00:13:27.978279+00:00", "confidence": 0.85, "source_url": "https://www.phfa.org/programs/assistance/keystone-advantage.aspx", "source_name": "PHFA – Keystone Advantage Assistance Loan Program"}, {"id": "943d1fc40e", "as_of": "2026-10 (PAR blog dated roughly Jan 2025)", "claim": "PHFA K-FIT (Keystone Forgivable in Ten Years) is a second mortgage for down payment/closing cost help, forgiven over 10 years; PA Association of Realtors reports eligible clients may receive 5% of the lesser of purchase price or appraised value with no maximum dollar amount, and K-FIT can be paired with the Keystone Home Loan and Keystone Flex. PHFA also offers a $500 PHFA Grant with the HFA Preferred (Lo MI) loan, combinable with Keystone Advantage.", "topic": "regulation", "saved_at": "2026-10-02T00:13:27.978279+00:00", "confidence": 0.75, "source_url": "https://www.phfa.org/programs/assistance.aspx", "source_name": "PHFA – Assistance Loans / PAR blog"}, {"id": "b3c9b6517c", "as_of": "2026-10 (current page)", "claim": "PHFA\'s Keystone Home Loan and Keystone Government loan require borrowers to meet PHFA income and purchase price limits; borrowers with under 20% down are required to obtain mortgage insurance. Keystone Flex with K-DATE offers eligible borrowers with loan amounts up to $150,000 assistance of 8% of the lesser of price or appraised value, subject to availability.", "topic": "regulation", "saved_at": "2026-10-02T00:13:27.978279+00:00", "confidence": 0.8, "source_url": "https://www.phfa.org/programs/homepurchase.aspx", "source_name": "PHFA – Home Purchase Programs"}, {"id": "7a7062f6ce", "as_of": "statute text; read 2026-10-02", "claim": "Pennsylvania Real Estate Seller Disclosure Law (68 Pa.C.S. §7303): any seller intending to transfer an interest in real property must disclose known material defects by completing all applicable items in a property disclosure statement, and deliver a signed, dated copy to the buyer before the seller and buyer sign an agreement of transfer. §7304: the State Real Estate Commission promulgates the form, which must cover subjects including seller\'s expertise, when last occupied, roof, and legal issues affecting title or use; sellers may use a form with additional provisions.", "topic": "regulation", "saved_at": "2026-10-02T00:13:27.978279+00:00", "confidence": 0.9, "source_url": "https://www.pa.gov/content/dam/copapwp-pagov/en/dos/department-and-offices/bpoa/real-estate/Seller%20Disclosure%20Law.pdf", "source_name": "PA Dept. of State – Seller Disclosure Law (68 Pa.C.S. Ch. 73)"}, {"id": "335da01721", "as_of": "2026", "claim": "Montgomery County (PA) 2026 adopted budget: county general fund real estate tax rate 5.462 mills plus Montgomery County Community College 0.49 mills (total 5.952 mills, up from 5.642 in 2025). The county says an average single-family home with $556,546 market value pays $935 in county real estate tax in 2026. The county\'s millage table lists county, municipal and school rates by municipality for 2026 (e.g., Ambler total 42.367 mills; Conshohocken 37.874 mills; Hatboro Borough 55.237 mills; figures as shown on the county page).", "topic": "taxes", "saved_at": "2026-10-02T00:13:27.978279+00:00", "confidence": 0.85, "source_url": "https://www.montgomerycountypa.gov/departments/board-assessment-appeals/county-municipality-millage-rates", "source_name": "Montgomery County PA – 2026 Adopted Budget and County & Municipality Millage Rates"}, {"id": "c41c962629", "as_of": "2026", "claim": "Montgomery County\'s adopted 2026 budget shows aggregate assessed value falling to roughly 39.5% of market value by 2022 (the county\'s last countywide reassessment was long ago, so assessments lag market values; the budget table lists a \'common level\' percentage trend, with 2022 market value $158.1B). Read from a budget table fragment; exact reassessment-year not verified.", "topic": "taxes", "saved_at": "2026-10-02T00:13:27.978279+00:00", "confidence": 0.5, "source_url": "https://assets.montgomerycountypa.gov/files/2026_Budget_Adopted-53254.pdf", "source_name": "Montgomery County PA – 2026 Adopted Budget"}, {"id": "8ac559c2e0", "as_of": "2026 (adopted 2025-12-10)", "claim": "Delaware County (PA) adopted its 2026 budget on December 10, 2025, with a county property tax rate of 4.609 mills, described by the county as a 19% revenue enhancement, averaging about $185 more per year for homeowners.", "topic": "taxes", "saved_at": "2026-10-02T00:13:27.978279+00:00", "confidence": 0.85, "source_url": "https://www.delcopa.gov/budget-management", "source_name": "Delaware County PA – FY2026 County Budget"}, {"id": "de86e75cab", "as_of": "FAQ undated (current page)", "claim": "Chester County (PA) assessment basics: per the county FAQ, assessments represent 100% of full market value as of the base year; the county\'s last countywide reassessment was effective 1998 (the county\'s FAQ references the mass appraisal model established before that reassessment), so assessments are on a long-ago base year and the county uses a Common Level Ratio. Property tax funds the county, 14 school districts and most of 73 municipalities. The Board of Assessment decision on appeals generally comes in 3-4 weeks; further appeal to Court of Common Pleas within 30 days.", "topic": "taxes", "saved_at": "2026-10-02T00:13:27.978279+00:00", "confidence": 0.7, "source_url": "https://www.chesco.org/Faq.aspx?QID=321", "source_name": "Chester County PA – Assessment FAQ"}, {"id": "276d558786", "as_of": "page read 2026-10-02 (page age ~2 years)", "claim": "Pennsylvania homestead/farmstead exclusion (Taxpayer Relief Act, Act 1 of Special Session 1 of 2006, signed June 27, 2006): reduces the assessed value of each qualifying homestead/farmstead by the same amount before school property tax is computed; only a primary residence is eligible; owners must file an application by March 1 preceding the tax year (tax years beginning July 1 or January 1). Per DCED, exclusion isn\'t guaranteed unless a voter-approved additional income tax or sufficient state allocations exist.", "topic": "taxes", "saved_at": "2026-10-02T00:13:27.978279+00:00", "confidence": 0.85, "source_url": "https://dced.pa.gov/local-government/property-tax-relief-homestead-exclusion/", "source_name": "PA DCED – Property Tax Relief / Homestead Exclusion"}], "state:VA": [{"id": "75bbb9a1a1", "as_of": "2026-10-02 (statute as cited in ruling)", "claim": "Virginia state recordation tax on deeds is 25 cents per $100 (or fraction) of the greater of consideration or actual value of the property conveyed (Va. Code § 58.1-801), per a Virginia Tax Commissioner ruling.", "topic": "taxes", "saved_at": "2026-10-02T00:56:48.738893+00:00", "confidence": 0.85, "source_url": "https://www.tax.virginia.gov/laws-rules-decisions/rulings-tax-commissioner/15-211", "source_name": "Virginia Department of Taxation – Tax Commissioner Ruling 15-211"}, {"id": "ad18b54bc6", "as_of": "2026-10-02", "claim": "Virginia Code § 58.1-802 imposes an additional grantor\'s tax of 50 cents per $500 (or fraction), excluding liens/encumbrances remaining at sale, on the greater of actual value or consideration. The Code states the tax is paid by the grantor (seller) or a person signing for the grantor.", "topic": "taxes", "saved_at": "2026-10-02T00:56:48.738893+00:00", "confidence": 0.85, "source_url": "https://www.tax.virginia.gov/laws-rules-decisions/rulings-tax-commissioner/16-178", "source_name": "Virginia Department of Taxation – Ruling 16-178; Code of Virginia Title 58.1 Ch. 8"}, {"id": "2c862de4f7", "as_of": "2026-10-02", "claim": "Local recordation tax example: the City of Alexandria levies local recordation tax equal to 1/3 of the state tax ($0.083 per $100), paid by the purchaser; state tax $0.25 per $100 paid by purchaser/designee; grantor\'s tax $0.50 per $500 paid by the grantor. Local rates vary by locality (this is a city, not a county).", "topic": "taxes", "saved_at": "2026-10-02T00:56:48.738893+00:00", "confidence": 0.8, "source_url": "https://www.alexandriava.gov/real-estate/recordation-tax", "source_name": "City of Alexandria – Recordation Tax"}, {"id": "25aee42219", "as_of": "2026-10-02", "claim": "Northern Virginia Regional Congestion Relief Fee (a grantor\'s tax) is $0.10 per $100 of sale price, typically paid by the seller in Northern Virginia Transportation Authority member jurisdictions. Alexandria\'s city page also lists an additional NoVA regional grantor\'s tax of $0.10 per $100. Older sources cite $0.15 (2013 original); a Loudoun County document says the fee was reinstituted at $0.10 on May 1, 2021.", "topic": "taxes", "saved_at": "2026-10-02T00:56:48.738893+00:00", "confidence": 0.8, "source_url": "https://thenovaauthority.org/financials/current-revenue-estimates", "source_name": "Northern Virginia Transportation Authority; Loudoun County Transportation District Fund document"}, {"id": "b4354a1e74", "as_of": "2026-10-02", "claim": "Under Virginia Residential Property Disclosure Act § 55.1-703 (version effective until Jan 1, 2027; a new version takes effect Jan 1, 2027), the owner of residential real property must furnish the purchaser a disclosure statement \'for the buyer to beware\' of matters that may affect the purchase decision; the statement is provided on the Real Estate Board website. Only this opening provision was read; the 2027 changes were not read.", "topic": "regulation", "saved_at": "2026-10-02T00:56:48.738893+00:00", "confidence": 0.8, "source_url": "https://law.lis.virginia.gov/vacodeupdates/title55.1/section55.1-703/", "source_name": "Virginia Law (law.lis.virginia.gov) § 55.1-703"}, {"id": "bcec42ecf3", "as_of": "Tax year 2026", "claim": "Loudoun County real estate tax rate for 2026 is $0.805 per $100 of assessed value, with an additional $0.20 for the Dulles Rail Service District and $0.105 for the Route 28 Highway Improvement district where applicable. Vehicle personal property tax is $3.09 per $100. (County-level, not town-specific.)", "topic": "taxes", "saved_at": "2026-10-02T00:56:48.738893+00:00", "confidence": 0.9, "source_url": "https://www.loudoun.gov/1922/Property-Tax-Rates", "source_name": "Loudoun County – Property Tax Rates 2026"}, {"id": "1a7022f04b", "as_of": "CY 2026", "claim": "Arlington County adopted real estate tax rate is $1.053 per $100 for calendar year 2026, up from $1.033 in CY2025.", "topic": "taxes", "saved_at": "2026-10-02T00:56:48.738893+00:00", "confidence": 0.85, "source_url": "https://www.arlingtonva.us/Government/Programs/Budget-Finance", "source_name": "Arlington County – Budget & Finance"}, {"id": "c39fd5519a", "as_of": "2026", "claim": "Prince William County 2026 real estate tax base rate is $0.865 per $100 of assessed value, plus a $0.0700 fire and rescue levy countywide (except Town of Quantico) and $0.0020 mosquito/forest pest district levy where applicable; also a stormwater fee (e.g., $67.28 for single-family detached per the county page). County-level.", "topic": "taxes", "saved_at": "2026-10-02T00:56:48.738893+00:00", "confidence": 0.85, "source_url": "https://www.pwcva.gov/department/tax-administration/tax-rates", "source_name": "Prince William County – Tax Rates 2026"}], "state:WV": [{"id": "155a08a760", "as_of": "2026-10-02 (statute as displayed)", "claim": "West Virginia imposes a state excise tax on real estate transfers of $1.10 for each $500 of value or fraction thereof (WV Code 11-22-2). Statute text also shows a $20 fee on transfers of real estate for consideration, and that beginning July 1, 2025 the revenue from this subsection is retained by the county where collected.", "topic": "taxes", "saved_at": "2026-10-02T00:58:48.513120+00:00", "confidence": 0.8, "source_url": "https://codes.findlaw.com/wv/chapter-11-taxation/wv-code-sect-11-22-2/", "source_name": "WV Code §11-22-2 (FindLaw)"}, {"id": "f451929a92", "as_of": "2026-10-02 (statute as displayed)", "claim": "Under WV Code 11-22-2(b), the additional county excise tax is 55 cents per $500 (or fraction); counties may raise it to equal the state rate, and after July 1, 2017 up to a maximum of $1.65 per $500 of value. The exact county rate varies by county, so confirm the specific county.", "topic": "taxes", "saved_at": "2026-10-02T00:58:48.513120+00:00", "confidence": 0.75, "source_url": "https://codes.findlaw.com/wv/chapter-11-taxation/wv-code-sect-11-22-2/", "source_name": "WV Code §11-22-2 (FindLaw); WV Tax Dept. rule 110-CSR-22"}, {"id": "f2e6658324", "as_of": "2017-06-19", "claim": "The WV State Tax Department\'s property transfer tax rule (110 CSR 22) states the state tax rate is $1.10 per $500 of value stated in the declaration of value, and notes SB 433 amendments letting counties increase the county excise tax. This is a 2017 filing, so the current rate comes from the statute.", "topic": "taxes", "saved_at": "2026-10-02T00:58:48.513120+00:00", "confidence": 0.8, "source_url": "https://tax.wv.gov/Documents/ProposedRules/PropertyTransferTax.110-CSR-22.pdf", "source_name": "WV Tax Department / Secretary of State, 110-CSR-22"}, {"id": "44dbb6e3e5", "as_of": "2026-10-02 (page as read)", "claim": "The WVHDF Homeownership Program offers 30-year fixed-rate loans financing up to 100% of the purchase price. It mainly targets first-time buyers. Gross income must not exceed the limit for the county of purchase, and the home price must not exceed the sales price limit for that county. Limits are set by county, and I did not retrieve the dollar figures.", "topic": "programs", "saved_at": "2026-10-02T00:58:48.513120+00:00", "confidence": 0.85, "source_url": "https://www.wvhdf.com/programs/single-family-programs-and-resources/homeownership-program/", "source_name": "West Virginia Housing Development Fund"}, {"id": "ae8422e2e8", "as_of": "2024-01-02 (may have been updated since)", "claim": "WVHDF states the Low Down Home Loan is offered only together with the Homeownership Program, a change noted on its page. As of January 2, 2024 it provides all buyers up to $8,000 in down payment and closing cost assistance regardless of loan-to-value ratio. It is a 15-year low-interest loan. Third-party sites quote up to $10,000, which conflicts with WVHDF\'s own page, so use the WVHDF figure and verify it is still current.", "topic": "programs", "saved_at": "2026-10-02T00:58:48.513120+00:00", "confidence": 0.7, "source_url": "https://www.wvhdf.com/introducing-the-low-down-home-loan/", "source_name": "West Virginia Housing Development Fund"}, {"id": "eaf4faf528", "as_of": "1999 bill text", "claim": "WV Code Chapter 36, Article 12 gives buyers a right to require the seller to disclose material defects in residential property. The seller\'s disclosure form is completed when the seller offers the property for sale, and the buyer may sign a waiver of that right. This is from 1999 SB 433 bill text, so the current codified language and how it applies in practice should be verified. A law-firm blog describes WV as caveat emptor, which is an unofficial source.", "topic": "regulation", "saved_at": "2026-10-02T00:58:48.513120+00:00", "confidence": 0.55, "source_url": "https://www.wvlegislature.gov/bill_status/bills_text.cfm?billdoc=SB433+SUB1+ENG.htm&yr=1999&sesstype=RS&i=433", "source_name": "WV Legislature, SB 433 (1999)"}, {"id": "d835fa4b58", "as_of": "2018 bill text", "claim": "WV Code 11-6B (Homestead Exemption): the first $20,000 of assessed value of an owner-occupied homestead is exempt from ad valorem property tax for owners aged 65 or older or certified permanently and totally disabled. The owner must have been a WV resident for the two consecutive calendar years before the tax year. This is the 2018 bill text, so check for later amendments.", "topic": "taxes", "saved_at": "2026-10-02T00:58:48.513120+00:00", "confidence": 0.65, "source_url": "https://www.wvlegislature.gov/bill_status/bills_text.cfm?billdoc=hb4442+intr.htm&yr=2018&sesstype=RS&i=4442", "source_name": "WV Legislature HB 4442 (2018)"}, {"id": "d4067395c8", "as_of": "2026", "claim": "West Virginia property is generally assessed at 60% of fair market value, and an example reduces assessed value by the $20,000 homestead exemption before local levy rates apply. The source cites the state Tax Department senior guide TSD-413. This is a secondary source and I did not read the primary guide.", "topic": "taxes", "saved_at": "2026-10-02T00:58:48.513120+00:00", "confidence": 0.5, "source_url": "https://grantsforseniors.org/property-tax-relief-for-seniors-in-west-virginia/", "source_name": "grantsforseniors.org (citing WV Tax Dept TSD-413)"}]}')


def upgrade() -> None:
    conn = op.get_bind()
    for scope, items in PACKS.items():
        exists = conn.execute(sa.text("SELECT 1 FROM shared_knowledge WHERE scope = :s"), {"s": scope}).first()
        if exists:
            continue
        conn.execute(
            sa.text("INSERT INTO shared_knowledge (id, scope, items, updated_at) VALUES (:id, :s, CAST(:items AS jsonb), now())"),
            {"id": str(uuid.uuid4()), "s": scope, "items": json.dumps(items)},
        )


def downgrade() -> None:
    op.get_bind().execute(sa.text("DELETE FROM shared_knowledge WHERE scope = ANY(:scopes)"), {"scopes": list(PACKS)})
